 async change(id,desired,context){
  if(!this.locks?.request)return {status:'CONCURRENCY_UNAVAILABLE'};
  return this.locks.request('man-bc:'+context.uid,{mode:'exclusive'},async()=>{
   const before=this.wishlist.read();if(before.uid!==context.uid||before.epoch!==context.epoch)return {status:'ACCOUNT_CHANGED'};
   let doc=null;try{doc=this.proofs(context.uid);}catch{/* Keep B usable; never overwrite an unreadable proof journal. */}
   const result=await this.wishlist.setSaved(id,desired,context);if(!result.ack)return result;
   const live=this.wishlist.read();if(live.uid!==context.uid||live.epoch!==context.epoch)return {status:'ACCOUNT_CHANGED'};
   if(!doc)return {...result,status:'PARTIAL_ACK',historyAck:false};
   if(desired&&!before.ids.includes(id)&&!doc.saves.some(e=>e.lessonId===id)){
