 constructor({storage,uid,catalog,locks,epoch=()=>0}){Object.assign(this,{storage,uid,catalog,locks,epoch});}
 key(uid){return 'xnot_favorites_uid_'+uid;}
 read(){const uid=this.uid(),epoch=this.epoch();if(!okUid(uid))return {status:'GUEST',uid:null,ids:[],entries:[],token:null};
  try{const token=this.storage.getItem(this.key(uid));const rows=token===null?[]:JSON.parse(token);if(!Array.isArray(rows)||rows.some(r=>!r||typeof r.id!=='string'||!r.id||r.id.length>160))throw Error('INVALID_DATA');
   const ids=[...new Set(rows.map(r=>r.id))];const catalog=this.catalog()||[];
   if(this.uid()!==uid||this.epoch()!==epoch)return {status:'ACCOUNT_CHANGED',uid:null,ids:[],entries:[]};
   return {status:'LOCAL',uid,epoch,token,ids,entries:ids.map(id=>{const lesson=catalog.find(u=>u.id===id&&official(u));return {id,available:!!lesson,name:lesson?.unitName||id};})};
  }catch{return {status:'UNAVAILABLE',uid,ids:[],entries:[],token:null};}}
 async setSaved(id,desired,{uid,token,epoch=this.epoch()}={}){
  if(!okUid(uid)||(this.uid()!==uid||this.epoch()!==epoch))return {status:'ACCOUNT_CHANGED'};
  if(typeof id!=='string'||typeof desired!=='boolean')return {status:'INVALID_INPUT'};
  if(!this.locks?.request)return {status:'CONCURRENCY_UNAVAILABLE'};
  try{return await this.locks.request('man-wishlist:'+uid,{mode:'exclusive'},()=>{
   if((this.uid()!==uid||this.epoch()!==epoch))return {status:'ACCOUNT_CHANGED'};
   const before=this.read();if(before.status!=='LOCAL')return before;
   if(desired&&!((this.catalog()||[]).some(u=>u.id===id&&official(u))))return {status:'LESSON_UNAVAILABLE'};
