   if(before.token!==token)return {status:'CONFLICT'};
   // Preserve existing metadata byte values for untouched entries; no bulk legacy normalization.
   const rows=before.token===null?[]:JSON.parse(before.token);
   const next=desired?[...rows,{id}]:rows.filter(x=>x.id!==id);
   if((this.uid()!==uid||this.epoch()!==epoch))return {status:'ACCOUNT_CHANGED'};
   const raw=JSON.stringify(next);
   this.storage.setItem(this.key(uid),raw);
   if(this.storage.getItem(this.key(uid))!==raw)return {status:'RESPONSE_UNKNOWN'};
   if((this.uid()!==uid||this.epoch()!==epoch))return {status:'ACCOUNT_CHANGED'};
   return {...this.read(),ack:true};
  });}catch{return {status:'UNAVAILABLE'};}
 }
}
