 if(!id(uid))throw Error('UID_REQUIRED');
 if(evidence?.uid!==uid||evidence?.schema!==1||!Array.isArray(evidence.events)||evidence.admission!=='VERIFIED_ADAPTER'||!id(evidence.summaryReceipt))throw Error('UNVERIFIED_EVIDENCE');
 if(wishlist?.uid!==uid||!Array.isArray(wishlist.ids))throw Error('WISHLIST_OWNER');
 if(previous&&(previous.uid!==uid||previous.schema!==1||!Array.isArray(previous.earned)))throw Error('STATE_OWNER_OR_SCHEMA');
 const known=new Set(TITLES.map(t=>t.id));
 if(previous?.earned.some(e=>!known.has(e.id)||!Array.isArray(e.receipts)||!e.receipts.length||e.receipts.some(r=>!id(r))))throw Error('INVALID_EARNED_STATE');
